import type { DhDomainCard } from '../model/types'

// ────────────────────────────────────────────────────────
// As 189 cartas de domínio do Livro Básico (9 domínios × 21 cartas, níveis 1 a 10).
// Gerado a partir do livro; texto em português, nomes conforme a edição brasileira.
// ────────────────────────────────────────────────────────

export const DOMAIN_CARDS: DhDomainCard[] = [
  { id: "rune-ward", domain: "arcano", level: 1, type: "feitico", recall: 0, name: "Proteção Rúnica", text: "Você tem um talismã pessoal que pode ser infundido com magia protetora e usado por você ou por um aliado. Descreva o que ele é e por que é importante para você. Quem estiver com a proteção pode gastar 1 Ponto de Esperança para reduzir o dano sofrido em 1d8. Se o Dado de Proteção resultar em 8, o poder da proteção se encerra depois de reduzir o dano neste turno. Ela pode ser recarregada sem custo no próximo descanso." },
  { id: "unleash-chaos", domain: "arcano", level: 1, type: "feitico", recall: 1, name: "Caos Liberto", text: "No início da sessão, coloque nesta carta um número de marcadores igual ao seu atributo de conjuração. Faça um teste de conjuração contra um alvo distante e gaste qualquer número de marcadores para canalizar energia bruta de dentro de você e liberá-la contra ele. Em um sucesso, role um número de d10 igual ao de marcadores gastos e cause o resultado como dano mágico ao alvo. Marque 1 Ponto de Fadiga para reabastecer a carta com marcadores (até o valor do seu atributo de conjuração). No fim de cada sessão, marcadores não utilizados são perdidos." },
  { id: "wall-walk", domain: "arcano", level: 1, type: "feitico", recall: 1, name: "Caminhar na Parede", text: "Gaste 1 Ponto de Esperança para que uma criatura que você possa tocar escale paredes e tetos com a mesma facilidade com que caminha no chão. O efeito dura até o fim da cena ou até você conjurar Caminhar na Parede novamente." },
  { id: "cinder-grasp", domain: "arcano", level: 2, type: "feitico", recall: 1, name: "Incendiar", text: "Faça um teste de conjuração contra um alvo corpo a corpo. Em um sucesso, o alvo irrompe em chamas, sofre 1d20+3 de dano mágico e fica temporariamente Em Chamas. Quando uma criatura Em Chamas age, ela sofre 2d6 de dano mágico adicional se ainda estiver Em Chamas no fim da ação." },
  { id: "floating-eye", domain: "arcano", level: 2, type: "feitico", recall: 0, name: "Olho Flutuante", text: "Gaste 1 Ponto de Esperança para criar um pequeno orbe flutuante que você pode mover para qualquer ponto em alcance muito distante. Enquanto o feitiço estiver ativo, você pode ver através do orbe como se estivesse olhando da posição dele, alternando livremente entre seus próprios sentidos e os do orbe. Se o orbe sofrer dano ou sair do alcance, o feitiço acaba." },
  { id: "counterspell", domain: "arcano", level: 3, type: "feitico", recall: 2, name: "Contramágica", text: "Você pode interromper um efeito mágico em andamento fazendo um teste de reação com seu atributo de conjuração. Em um sucesso, o efeito é interrompido, as consequências são evitadas e esta carta vai para a sua reserva." },
  { id: "flight", domain: "arcano", level: 3, type: "feitico", recall: 1, name: "Voo", text: "Faça um teste de conjuração (15). Em um sucesso, coloque nesta carta um número de marcadores igual à sua Agilidade (mínimo 1). Ao fazer um teste enquanto voa, gaste um marcador desta carta. Depois que a ação que gasta o último marcador for resolvida, você desce até o chão logo abaixo." },
  { id: "blink-out", domain: "arcano", level: 4, type: "feitico", recall: 1, name: "Translocação", text: "Faça um teste de conjuração (12). Em um sucesso, gaste 1 Ponto de Esperança para se teletransportar para outro ponto visível em alcance distante. Se houver criaturas voluntárias em alcance muito próximo, gaste 1 Ponto de Esperança adicional por criatura para levá-las com você." },
  { id: "preservation-blast", domain: "arcano", level: 4, type: "feitico", recall: 2, name: "Explosão Defensiva", text: "Faça um teste de conjuração contra todos os alvos corpo a corpo. Os alvos em que você tiver sucesso são empurrados para alcance distante e sofrem d8+3 de dano mágico, usando seu atributo de conjuração." },
  { id: "chain-lightning", domain: "arcano", level: 5, type: "feitico", recall: 1, name: "Corrente de Relâmpagos", text: "Marque 2 Pontos de Fadiga para fazer um teste de conjuração, liberando relâmpagos contra todos os alvos em alcance próximo. Os alvos em que você tiver sucesso devem fazer um teste de reação com Dificuldade igual ao resultado do seu teste de conjuração. Os que falharem sofrem 2d8+4 de dano mágico. Adversários que ainda não foram atingidos por Corrente de Relâmpagos e estejam em alcance próximo de alvos anteriores que sofreram dano também devem fazer o teste de reação, e os que falharem sofrem 2d8+4 de dano mágico. A corrente continua até não haver mais adversários ao alcance." },
  { id: "premonition", domain: "arcano", level: 5, type: "feitico", recall: 2, name: "Premonição", text: "Você pode canalizar energia arcana para ter visões do futuro. Uma vez por descanso longo, logo depois de o mestre descrever as consequências de um teste seu, você pode anular essa jogada e suas consequências, como se nunca tivessem acontecido, e fazer outra jogada no lugar." },
  { id: "rift-walker", domain: "arcano", level: 6, type: "feitico", recall: 2, name: "Fenda Espacial", text: "Faça um teste de conjuração (15). Em um sucesso, você faz uma marca arcana no chão onde está. Na próxima vez que conjurar Fenda Espacial com sucesso, abre-se uma fenda no espaço que dá passagem segura até o ponto exato onde a marca foi feita. A fenda permanece aberta até você fechá-la ou conjurar outro feitiço. Você pode cancelar o feitiço a qualquer momento para conjurar Fenda Espacial de novo e marcar outro lugar." },
  { id: "telekinesis", domain: "arcano", level: 6, type: "feitico", recall: 0, name: "Telecinese", text: "Faça um teste de conjuração contra um alvo distante. Em um sucesso, você pode usar a mente para movê-lo para qualquer ponto em alcance distante da posição original. Você também pode arremessá-lo como um ataque, fazendo um teste de conjuração adicional contra o segundo alvo. Em um sucesso, cause d12+4 de dano físico ao segundo alvo, usando sua Proficiência. Depois disso, o feitiço acaba." },
  { id: "arcana-touched", domain: "arcano", level: 7, type: "talento", recall: 2, name: "Dom Arcano", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Arcano, receba os seguintes benefícios:\n• Bônus de +1 em testes de conjuração;\n• Uma vez por descanso, você pode trocar entre si os resultados dos Dados de Esperança e de Medo." },
  { id: "cloaking-blast", domain: "arcano", level: 7, type: "feitico", recall: 2, name: "Ocultação", text: "Ao ter sucesso em um teste de conjuração para conjurar um feitiço diferente, você pode gastar 1 Ponto de Esperança para ficar Oculto. Enquanto estiver Oculto, você permanece sem ser visto se estiver parado quando um adversário se mover para onde normalmente o veria. Ao entrar na linha de visão de um adversário (ou se mover dentro dela) ou ao atacar, você deixa de estar Oculto." },
  { id: "arcane-reflection", domain: "arcano", level: 8, type: "feitico", recall: 1, name: "Reflexo Arcano", text: "Ao sofrer dano mágico, você pode gastar qualquer número de Pontos de Esperança para rolar essa quantidade de d6. Se algum resultado for 6, o ataque é refletido de volta ao conjurador, que sofre o dano no seu lugar." },
  { id: "confusing-aura", domain: "arcano", level: 8, type: "feitico", recall: 2, name: "Aura de Confusão", text: "Faça um teste de conjuração (14). Uma vez por descanso longo, em um sucesso, você cria uma camada de ilusão sobre o corpo que dificulta saber exatamente onde você está. Marque qualquer número de Pontos de Fadiga para criar essa quantidade de camadas adicionais. Quando um adversário atacar você, role um número de d6 igual ao de camadas ativas. Se algum resultado for 5 ou mais, uma camada da aura é destruída e o ataque falha. Se todos forem 4 ou menos, você sofre o dano e o feitiço acaba." },
  { id: "earthquake", domain: "arcano", level: 9, type: "feitico", recall: 2, name: "Terremoto", text: "Faça um teste de conjuração (16). Uma vez por descanso, em um sucesso, todos os alvos em alcance muito distante que não estejam voando devem fazer um teste de reação (18). Os que falharem sofrem 3d10+8 de dano físico e ficam temporariamente Vulneráveis. Os que tiverem sucesso sofrem metade do dano. Além disso, ao ter sucesso no teste de conjuração, todo o terreno em alcance muito distante se torna difícil de atravessar e estruturas nessa área podem sofrer danos ou desabar." },
  { id: "sensory-projection", domain: "arcano", level: 9, type: "feitico", recall: 0, name: "Projeção Sensorial", text: "Uma vez por descanso, faça um teste de conjuração (15). Em um sucesso, você mergulha em uma visão que permite ver e ouvir com clareza qualquer lugar em que já esteve, como se estivesse ali naquele momento. Você pode se mover livremente na visão, sem as limitações de um corpo físico. Este feitiço não pode ser detectado por meios mundanos ou mágicos. Você sai da visão ao sofrer dano ou conjurar outro feitiço." },
  { id: "adjust-reality", domain: "arcano", level: 10, type: "feitico", recall: 1, name: "Ajustar Realidade", text: "Depois que você ou um aliado voluntário fizer qualquer teste, você pode gastar 5 Pontos de Esperança para mudar o resultado numérico dessa jogada para um valor à sua escolha. O resultado deve ser plausível dentro do alcance dos dados." },
  { id: "falling-sky", domain: "arcano", level: 10, type: "feitico", recall: 1, name: "Queda do Céu", text: "Faça um teste de conjuração contra todos os adversários em alcance distante. Marque qualquer número de Pontos de Fadiga para fazer estilhaços arcanos chuvarem do alto. Os alvos em que você tiver sucesso sofrem 1d20+2 de dano mágico para cada Ponto de Fadiga marcado." },
  { id: "get-back-up", domain: "lamina", level: 1, type: "talento", recall: 1, name: "Levante-se", text: "Ao sofrer dano grave, você pode marcar 1 Ponto de Fadiga para reduzir a gravidade em uma categoria." },
  { id: "not-good-enough", domain: "lamina", level: 1, type: "talento", recall: 1, name: "Não o Suficiente", text: "Ao rolar seus dados de dano, você pode rolar novamente qualquer resultado 1 ou 2." },
  { id: "whirlwind", domain: "lamina", level: 1, type: "talento", recall: 0, name: "Turbilhão", text: "Ao acertar um ataque contra um alvo em alcance muito próximo, você pode gastar 1 Ponto de Esperança para usar esse ataque contra todos os outros alvos em alcance muito próximo. Os adversários adicionais em que você tiver sucesso sofrem metade do dano." },
  { id: "a-soldiers-bond", domain: "lamina", level: 2, type: "talento", recall: 1, name: "Fraternidade Marcial", text: "Uma vez por descanso longo, ao elogiar alguém ou perguntar sobre algo em que essa pessoa é boa, vocês dois recebem 3 Pontos de Esperança." },
  { id: "reckless", domain: "lamina", level: 2, type: "talento", recall: 1, name: "Ataque Imprudente", text: "Marque 1 Ponto de Fadiga para receber vantagem em um ataque." },
  { id: "scramble", domain: "lamina", level: 3, type: "talento", recall: 1, name: "Mexa-se", text: "Uma vez por descanso, quando uma criatura em alcance corpo a corpo for causar dano a você, você pode evitar o ataque e se afastar com segurança do alcance corpo a corpo do inimigo." },
  { id: "versatile-fighter", domain: "lamina", level: 3, type: "talento", recall: 1, name: "Versatilidade", text: "Você pode usar um atributo diferente para uma arma equipada, em vez do atributo que a arma pede. Ao causar dano, você pode marcar 1 Ponto de Fadiga para usar o resultado máximo de um dos seus dados de dano em vez de rolá-lo." },
  { id: "deadly-focus", domain: "lamina", level: 4, type: "talento", recall: 2, name: "Concentração Mortal", text: "Uma vez por descanso, você pode dedicar todo o seu foco a um alvo à sua escolha. Até atacar outra criatura, derrotar o alvo ou a batalha acabar, receba +1 de bônus na Proficiência." },
  { id: "fortified-armor", domain: "lamina", level: 4, type: "talento", recall: 0, name: "Armadura Fortificada", text: "Enquanto estiver usando armadura, receba +2 de bônus nos limiares de dano." },
  { id: "champions-edge", domain: "lamina", level: 5, type: "talento", recall: 1, name: "Vantagem do Campeão", text: "Ao ter sucesso crítico em um ataque, você pode gastar até 3 Pontos de Esperança e escolher uma das opções a seguir para cada Ponto gasto:\n• Você recupera 1 Ponto de Vida;\n• Você recupera 1 Ponto de Armadura;\n• O alvo deve marcar 1 Ponto de Vida adicional.\nVocê não pode escolher a mesma opção mais de uma vez." },
  { id: "vitality", domain: "lamina", level: 5, type: "talento", recall: 0, name: "Vitalidade", text: "Ao escolher esta carta, receba permanentemente dois dos benefícios a seguir:\n• 1 espaço de Fadiga;\n• 1 espaço de Vida;\n• +2 de bônus nos limiares de dano.\nDepois, coloque esta carta permanentemente na sua reserva." },
  { id: "battle-hardened", domain: "lamina", level: 6, type: "talento", recall: 2, name: "Calejado pela Batalha", text: "Uma vez por descanso longo, ao fazer um Movimento de Morte, você pode gastar 1 Ponto de Esperança para recuperar 1 Ponto de Vida em vez disso." },
  { id: "rage-up", domain: "lamina", level: 6, type: "talento", recall: 1, name: "Fúria", text: "Antes de fazer um ataque, você pode marcar 1 Ponto de Fadiga para receber um bônus na rolagem de dano igual ao dobro da sua Força. Você pode usar Fúria duas vezes por ataque." },
  { id: "blade-touched", domain: "lamina", level: 7, type: "talento", recall: 1, name: "Dom da Lâmina", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Lâmina, receba os benefícios a seguir:\n• +2 de bônus em testes de ataque;\n• +4 de bônus no limiar de dano grave." },
  { id: "glancing-blow", domain: "lamina", level: 7, type: "talento", recall: 1, name: "Golpe de Raspão", text: "Ao errar um ataque, você pode marcar 1 Ponto de Fadiga para causar dano de arma usando metade da sua Proficiência." },
  { id: "battle-cry", domain: "lamina", level: 8, type: "talento", recall: 2, name: "Grito de Guerra", text: "Uma vez por descanso longo, ao avançar para o perigo, você pode soltar um brado inspirador. Todos os aliados que puderem ouvi-lo recuperam 1 Ponto de Fadiga e recebem 1 Ponto de Esperança. Além disso, seus aliados têm vantagem em testes de ataque até você ou um aliado falhar com Medo." },
  { id: "frenzy", domain: "lamina", level: 8, type: "talento", recall: 3, name: "Frenesi", text: "Uma vez por descanso longo, você pode entrar em Frenesi até não haver mais adversários à vista. Enquanto estiver em Frenesi, você não pode usar Pontos de Armadura e recebe +10 de bônus nas rolagens de dano e +8 de bônus no limiar de dano grave." },
  { id: "gore-and-glory", domain: "lamina", level: 9, type: "talento", recall: 2, name: "Guerra e Glória", text: "Ao ter sucesso crítico em um ataque com arma, receba 1 Ponto de Esperança adicional ou recupere 1 Ponto de Fadiga adicional. Além disso, quando causar dano suficiente para derrotar um inimigo, receba 1 Ponto de Esperança ou recupere 1 Ponto de Fadiga." },
  { id: "reapers-strike", domain: "lamina", level: 9, type: "talento", recall: 3, name: "Golpe da Morte", text: "Uma vez por descanso longo, gaste 1 Ponto de Esperança para fazer um teste de ataque. O mestre diz em quais alvos ao alcance ele teria sucesso. Escolha um desses alvos e force-o a marcar 5 Pontos de Vida." },
  { id: "battle-monster", domain: "lamina", level: 10, type: "talento", recall: 0, name: "Monstro de Batalha", text: "Ao acertar um ataque contra um adversário, você pode marcar 4 Pontos de Fadiga para forçar o alvo a marcar um número de Pontos de Vida igual ao número de Pontos de Vida que você tem marcados, em vez de rolar o dano." },
  { id: "onslaught", domain: "lamina", level: 10, type: "talento", recall: 3, name: "Massacrar", text: "Ao acertar um ataque com sua arma, você nunca causa dano abaixo do limiar de dano maior do alvo (o alvo sempre marca no mínimo 2 Pontos de Vida). Além disso, quando uma criatura ao alcance da sua arma causar dano a um aliado com um ataque que não inclua você, você pode marcar 1 Ponto de Fadiga para forçá-la a fazer um teste de reação (15). Em uma falha, ela deve marcar 1 Ponto de Vida." },
  { id: "deft-maneuvers", domain: "falange", level: 1, type: "talento", recall: 0, name: "Movimento Ligeiro", text: "Uma vez por descanso, marque 1 Ponto de Fadiga para correr até qualquer ponto em alcance distante sem fazer um teste de Agilidade. Se terminar esse movimento em alcance corpo a corpo de um adversário e atacá-lo imediatamente, receba +1 de bônus no teste de ataque." },
  { id: "i-see-it-coming", domain: "falange", level: 1, type: "talento", recall: 1, name: "Um Passo à Frente", text: "Quando for alvo de um ataque feito de fora do alcance corpo a corpo, você pode marcar 1 Ponto de Fadiga para rolar 1d4 e receber um bônus na Evasão igual ao resultado contra esse ataque." },
  { id: "untouchable", domain: "falange", level: 1, type: "talento", recall: 1, name: "Intocável", text: "Receba um bônus na Evasão igual à metade da sua Agilidade." },
  { id: "ferocity", domain: "falange", level: 2, type: "talento", recall: 2, name: "Ferocidade", text: "Quando fizer um adversário marcar 1 ou mais Pontos de Vida, você pode gastar 2 Pontos de Esperança para aumentar sua Evasão pelo número de Pontos de Vida que ele marcou. O bônus dura até depois do próximo ataque feito contra você." },
  { id: "strategic-approach", domain: "falange", level: 2, type: "talento", recall: 1, name: "Aproximação Estratégica", text: "Depois de um descanso longo, coloque nesta carta um número de marcadores igual ao seu Conhecimento (mínimo 1). Na primeira vez que se mover até alcance próximo de um adversário e atacá-lo, você pode gastar 1 marcador para escolher uma das opções:\n• Você faz o ataque com vantagem;\n• Você recupera 1 Ponto de Fadiga de um aliado em alcance corpo a corpo do adversário;\n• Você soma 1d8 à rolagem de dano.\nAo fazer um descanso longo, perca os marcadores não utilizados." },
  { id: "brace", domain: "falange", level: 3, type: "talento", recall: 1, name: "Reforço", text: "Ao marcar 1 Ponto de Armadura para reduzir o dano sofrido, você pode marcar 1 Ponto de Fadiga para marcar 1 Ponto de Armadura adicional." },
  { id: "tactician", domain: "falange", level: 3, type: "talento", recall: 1, name: "Táticas", text: "Ao Ajudar um Aliado, ele pode gastar 1 Ponto de Esperança para somar uma das suas Experiências à jogada, junto com seu dado de vantagem. Ao fazer um teste em dupla, você pode rolar 1d20 como seu Dado de Esperança." },
  { id: "boost", domain: "falange", level: 4, type: "talento", recall: 1, name: "Impulso", text: "Marque 1 Ponto de Fadiga para se impulsionar em um aliado voluntário em alcance próximo, lançando-se ao ar para realizar um ataque aéreo contra um alvo em alcance distante. Você tem vantagem no ataque, soma 1d10 à rolagem de dano e termina o movimento em alcance corpo a corpo do alvo." },
  { id: "redirect", domain: "falange", level: 4, type: "talento", recall: 1, name: "Redirecionar", text: "Quando um ataque feito contra você de fora do alcance corpo a corpo falhar, role um número de d6 igual à sua Proficiência. Se algum resultado for 6, você pode marcar 1 Ponto de Fadiga para redirecionar o ataque e causar dano a um adversário em alcance muito próximo." },
  { id: "know-thy-enemy", domain: "falange", level: 5, type: "talento", recall: 1, name: "Conheça Seu Inimigo", text: "Ao observar uma criatura, você pode fazer um teste de Instinto contra ela. Em um sucesso, gaste 1 Ponto de Esperança e peça ao mestre um conjunto de informações sobre o alvo, entre as opções:\n• Seus Pontos de Vida e de Fadiga desmarcados;\n• Sua Dificuldade e limiares de dano;\n• Suas táticas e os dados de dano do ataque padrão;\n• Suas habilidades e Experiências.\nAlém disso, em um sucesso, você pode marcar 1 Ponto de Fadiga para remover 1 Ponto de Medo da reserva do mestre." },
  { id: "signature-move", domain: "falange", level: 5, type: "talento", recall: 1, name: "Golpe Característico", text: "Dê um nome e descreva seu golpe característico de combate. Uma vez por descanso, ao realizar esse golpe como parte de uma ação, você pode rolar 1d20 como seu Dado de Esperança. Em um sucesso, recupere 1 Ponto de Fadiga." },
  { id: "rapid-riposte", domain: "falange", level: 6, type: "talento", recall: 0, name: "Contra-ataque Rápido", text: "Quando um ataque feito contra você em alcance corpo a corpo falhar, você pode marcar 1 Ponto de Fadiga e aproveitar a brecha para causar ao atacante o dano de arma de uma das suas armas ativas." },
  { id: "recovery", domain: "falange", level: 6, type: "talento", recall: 1, name: "Recuperação", text: "Durante um descanso curto, você pode escolher um movimento de descanso longo em vez de um curto. Você pode gastar 1 Ponto de Esperança para permitir que um aliado faça o mesmo." },
  { id: "bone-touched", domain: "falange", level: 7, type: "talento", recall: 2, name: "Dom da Falange", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Falange, receba os benefícios a seguir:\n• +1 de bônus em Agilidade;\n• Uma vez por descanso, você pode gastar 3 Pontos de Esperança para fazer um ataque que teve sucesso contra você falhar." },
  { id: "cruel-precision", domain: "falange", level: 7, type: "talento", recall: 1, name: "Acuidade Cruel", text: "Ao acertar um ataque com arma, receba um bônus na rolagem de dano igual à sua Acuidade ou à sua Agilidade." },
  { id: "breaking-blow", domain: "falange", level: 8, type: "talento", recall: 3, name: "Golpe Debilitante", text: "Ao acertar um ataque, você pode marcar 1 Ponto de Fadiga para fazer o próximo ataque bem-sucedido contra esse mesmo alvo causar 2d12 de dano adicional." },
  { id: "wrangle", domain: "falange", level: 8, type: "talento", recall: 1, name: "Amontoar", text: "Faça um teste de Agilidade contra todos os alvos em alcance próximo. Gaste 1 Ponto de Esperança para mover os alvos em que teve sucesso, e quaisquer aliados voluntários em alcance próximo, para outro ponto em alcance próximo." },
  { id: "on-the-brink", domain: "falange", level: 9, type: "talento", recall: 1, name: "Quase Lá", text: "Enquanto tiver 2 ou menos Pontos de Vida desmarcados, você não sofre dano menor." },
  { id: "splintering-strike", domain: "falange", level: 9, type: "talento", recall: 3, name: "Ataque Fragmentado", text: "Gaste 1 Ponto de Esperança e ataque todos os adversários ao alcance da sua arma. Uma vez por descanso longo, em um sucesso contra qualquer alvo, some todo o dano causado e redistribua-o como quiser entre os alvos em que teve sucesso. Ao causar dano a um alvo, role um dado de dano adicional e some o resultado ao dano causado a esse alvo." },
  { id: "deathrun", domain: "falange", level: 10, type: "talento", recall: 1, name: "Trajeto Mortal", text: "Gaste 3 Pontos de Esperança para correr em linha reta pelo campo de batalha até um ponto em alcance distante, atacando todos os adversários ao alcance da sua arma ao longo do trajeto. Escolha a ordem em que causa dano aos alvos em que teve sucesso. No primeiro, role o dano da arma com +1 de bônus na Proficiência. Depois, remova um dado da rolagem e cause o dano restante ao alvo seguinte. Continue removendo um dado por alvo até não restarem dados ou adversários. Você não pode atingir o mesmo adversário mais de uma vez por ataque." },
  { id: "swift-step", domain: "falange", level: 10, type: "talento", recall: 2, name: "Passo Célere", text: "Quando um ataque feito contra você falhar, recupere 1 Ponto de Fadiga. Se não puder recuperar Fadiga, receba 1 Ponto de Esperança." },
  { id: "book-of-ava", domain: "codice", level: 1, type: "grimorio", recall: 2, name: "Livro de Ava", text: "Propelir: faça um teste de conjuração contra um alvo corpo a corpo. Em um sucesso, ele é empurrado para alcance distante e sofre d10+2 de dano mágico, usando sua Proficiência.\nArmadura de Tava: gaste 1 Ponto de Esperança para dar a um alvo que você possa tocar +1 de bônus na Armadura até o próximo descanso ou até conjurar Armadura de Tava novamente.\nEspinho de Gelo: faça um teste de conjuração (12) para invocar um grande espinho de gelo em alcance distante. Se usá-lo como arma, faça o teste de conjuração contra a Dificuldade do alvo. Em um sucesso, cause d6 de dano físico, usando sua Proficiência." },
  { id: "book-of-illiat", domain: "codice", level: 1, type: "grimorio", recall: 2, name: "Livro de Illiat", text: "Sono: faça um teste de conjuração contra um alvo em alcance muito próximo. Em um sucesso, ele fica Adormecido até sofrer dano ou até o mestre gastar 1 Ponto de Medo no turno dele para remover essa condição.\nSaraivada Arcana: uma vez por descanso, gaste qualquer número de Pontos de Esperança e dispare projéteis mágicos contra um alvo à sua escolha em alcance próximo. Role um número de d6 igual aos Pontos gastos e cause esse total como dano mágico ao alvo.\nTelepatia: gaste 1 Ponto de Esperança para abrir um canal de comunicação mental com um alvo que você possa ver. A conexão dura até o próximo descanso ou até você conjurar Telepatia novamente." },
  { id: "book-of-tyfar", domain: "codice", level: 1, type: "grimorio", recall: 2, name: "Livro de Tyfar", text: "Chama Selvagem: faça um teste de conjuração contra até três adversários em alcance corpo a corpo. Os alvos em que você tiver sucesso sofrem 2d6 de dano mágico e devem marcar 1 Ponto de Fadiga enquanto chamas irrompem da sua mão.\nMão Mágica: você conjura uma mão mágica, com o mesmo tamanho e a mesma força da sua, em alcance distante.\nNévoa Misteriosa: faça um teste de conjuração (13) para criar uma névoa espessa e temporária em uma área fixa em alcance muito próximo. A névoa obscurece muito a área e tudo dentro dela." },
  { id: "book-of-sitil", domain: "codice", level: 2, type: "grimorio", recall: 2, name: "Livro de Sitil", text: "Alterar Aparência: você muda magicamente sua aparência e suas roupas para não ser reconhecido.\nParalela: gaste 2 Pontos de Esperança para conjurar este feitiço em você ou em um aliado em alcance próximo. Na próxima vez que o alvo atacar, ele pode atingir um alvo adicional ao alcance em que o teste de ataque dele teria sucesso. Você só pode manter este feitiço em uma criatura por vez.\nIlusão: faça um teste de conjuração (14). Em um sucesso, crie uma ilusão visual temporária, de tamanho máximo igual ao seu, em alcance próximo, que dura enquanto você olhar para ela. Ela resiste a um exame até um observador chegar em alcance corpo a corpo." },
  { id: "book-of-vagras", domain: "codice", level: 2, type: "grimorio", recall: 2, name: "Livro de Vagras", text: "Trava Rúnica: faça um teste de conjuração (15) em um objeto que você esteja tocando e que possa ser fechado (como uma fechadura, um baú ou uma caixa). Uma vez por descanso, em um sucesso, você pode trancá-lo de modo que apenas criaturas à sua escolha possam abri-lo. Alguém com acesso à magia e uma hora para estudar o feitiço pode quebrá-lo.\nPorta Arcana: quando não houver adversários em alcance corpo a corpo, faça um teste de conjuração (13). Em um sucesso, gaste 1 Ponto de Esperança para criar um portal do ponto onde você está até um ponto visível em alcance distante. Ele se fecha depois que uma criatura o atravessa.\nRevelar: faça um teste de conjuração. Se houver algo escondido por magia em alcance próximo, ele é revelado." },
  { id: "book-of-korvax", domain: "codice", level: 3, type: "grimorio", recall: 2, name: "Livro de Korvax", text: "Levitação: faça um teste de conjuração para erguer temporariamente um alvo que você possa ver e movê-lo para um ponto em alcance próximo da posição original.\nRetratação: gaste 1 Ponto de Esperança para forçar um alvo em alcance corpo a corpo a fazer um teste de reação (15). Em uma falha, ele esquece o último minuto da conversa de vocês.\nCírculo Rúnico: marque 1 Ponto de Fadiga para criar um círculo mágico temporário no chão onde você está. Todos os adversários em alcance corpo a corpo, ou que entrarem nele, sofrem 2d12+4 de dano mágico e são empurrados para alcance muito próximo." },
  { id: "book-of-norai", domain: "codice", level: 3, type: "grimorio", recall: 2, name: "Livro de Norai", text: "Laço Místico: faça um teste de conjuração contra um alvo em alcance distante. Em um sucesso, ele fica temporariamente Imobilizado e deve marcar 1 Ponto de Fadiga. Se o alvo estiver voando, o feitiço o derruba e o Imobiliza temporariamente.\nBola de Fogo: faça um teste de conjuração contra um alvo em alcance muito distante. Em um sucesso, arremesse uma esfera de fogo que explode no impacto. O alvo e todas as criaturas em alcance muito próximo dele devem fazer um teste de reação (13). Os que falharem sofrem d20+5 de dano mágico, usando sua Proficiência. Os que tiverem sucesso sofrem metade do dano." },
  { id: "book-of-exota", domain: "codice", level: 4, type: "grimorio", recall: 3, name: "Livro de Ecsota", text: "Repúdio: você pode interromper um efeito mágico em andamento. Faça um teste de reação com seu atributo de conjuração. Uma vez por descanso, em um sucesso, o efeito é interrompido e as consequências são evitadas.\nCriar Constructo: gaste 1 Ponto de Esperança para escolher um grupo de objetos ao redor e criar com eles um constructo animado que obedece a comandos simples. Faça um teste de conjuração para ordenar que ajam. Quando necessário, eles compartilham sua Evasão e seus atributos, e seus ataques causam 2d10+3 de dano físico. Você só pode manter um constructo por vez, e ele se desfaz ao sofrer qualquer dano." },
  { id: "book-of-grynn", domain: "codice", level: 4, type: "grimorio", recall: 2, name: "Livro de Grynn", text: "Deflexão Arcana: uma vez por descanso longo, gaste 1 Ponto de Esperança para anular o dano de um ataque contra você ou contra um aliado em alcance muito próximo.\nTrava Temporal: escolha um objeto em alcance distante. Ele para no tempo e no espaço, exatamente onde está, até o próximo descanso. Se uma criatura tentar movê-lo, faça um teste de conjuração contra ela para manter o feitiço.\nMuralha de Chamas: faça um teste de conjuração (15). Em um sucesso, crie uma muralha de chamas mágicas entre dois pontos em alcance distante. Todas as criaturas no caminho devem escolher um lado, e tudo que atravessar a muralha depois sofre 4d10+3 de dano mágico." },
  { id: "manifest-wall", domain: "codice", level: 5, type: "feitico", recall: 2, name: "Muralha", text: "Faça um teste de conjuração (15). Uma vez por descanso, em um sucesso, gaste 1 Ponto de Esperança para criar uma muralha mágica temporária entre dois pontos em alcance distante. Ela pode ter até 15 metros de altura e se formar em qualquer ângulo. Criaturas ou objetos no caminho são empurrados para um lado à sua escolha. A muralha permanece até o próximo descanso ou até você conjurar Muralha novamente." },
  { id: "teleport", domain: "codice", level: 5, type: "feitico", recall: 2, name: "Teleporte", text: "Uma vez por descanso longo, você pode teletransportar instantaneamente a si mesmo e qualquer número de alvos voluntários em alcance próximo para um lugar onde já esteve. Escolha uma das opções a seguir e faça um teste de conjuração (16):\n• Se você conhece muito bem o lugar, receba +3 de bônus;\n• Se já visitou o lugar com frequência, receba +1 de bônus;\n• Se visitou o lugar poucas vezes, sem modificador;\n• Se esteve lá apenas uma vez, receba −2 de penalidade.\nEm um sucesso, você aparece onde pretendia. Em uma falha, você aparece fora do destino, e a margem da falha define o quanto." },
  { id: "banish", domain: "codice", level: 6, type: "feitico", recall: 0, name: "Banir", text: "Faça um teste de conjuração contra um alvo em alcance próximo. Em um sucesso, role um número de d20 igual ao seu atributo de conjuração. O alvo deve fazer um teste de reação com Dificuldade igual ao seu maior resultado. Se tiver sucesso, ele deve marcar 1 Ponto de Fadiga, mas não é banido. Uma vez por descanso, em uma falha, ele é banido deste plano. Quando os personagens rolarem com Medo, a Dificuldade recebe −1 de penalidade e o alvo faz outro teste de reação. Em um sucesso, ele retorna do banimento." },
  { id: "sigil-of-retribution", domain: "codice", level: 6, type: "feitico", recall: 2, name: "Sigilo da Retaliação", text: "Marque um adversário em alcance próximo com um sigilo de retaliação. O mestre recebe 1 Ponto de Medo. Quando o adversário marcado causar dano a você ou a seus aliados, coloque 1d8 nesta carta. Você pode guardar um número de d8 igual ao seu nível. Quando acertar um ataque no adversário marcado, role os dados desta carta, some o total à rolagem de dano e remova os dados. O efeito acaba quando o adversário marcado for derrotado ou você conjurar Sigilo da Retaliação novamente." },
  { id: "book-of-homet", domain: "codice", level: 7, type: "grimorio", recall: 0, name: "Livro de Homet", text: "Atravessar: faça um teste de conjuração (13). Uma vez por descanso, em um sucesso, você e todas as criaturas que estiverem tocando você podem atravessar uma parede ou porta em alcance próximo. O efeito acaba quando todos estiverem do outro lado.\nPortal Planar: faça um teste de conjuração (14). Uma vez por descanso longo, em um sucesso, abra um portal para um lugar de outra dimensão ou plano de existência onde você já esteve. O portal dura até o próximo descanso." },
  { id: "codex-touched", domain: "codice", level: 7, type: "talento", recall: 2, name: "Dom do Códice", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Códice, receba os benefícios a seguir:\n• Você pode marcar 1 Ponto de Fadiga para somar sua Proficiência a um teste de conjuração;\n• Uma vez por descanso, substitua esta carta por qualquer carta da sua reserva sem pagar o custo de troca dela." },
  { id: "book-of-vyola", domain: "codice", level: 8, type: "grimorio", recall: 2, name: "Livro de Vyola", text: "Mergulho na Memória: faça um teste de conjuração contra um alvo em alcance distante. Em um sucesso, vasculhe a mente do alvo e faça uma pergunta ao mestre, que descreve as lembranças do alvo relacionadas à resposta.\nClareza Compartilhada: uma vez por descanso longo, gaste 1 Ponto de Esperança para escolher duas criaturas voluntárias. Quando uma delas for marcar Fadiga, elas podem escolher entre si quem marca. O feitiço dura até o próximo descanso delas." },
  { id: "safe-haven", domain: "codice", level: 8, type: "feitico", recall: 3, name: "Refúgio Seguro", text: "Quando tiver alguns minutos de calma para se concentrar, você pode gastar 2 Pontos de Esperança para invocar seu Refúgio Seguro, um grande lar interdimensional onde você e seus aliados podem se abrigar. Uma porta mágica surge em algum ponto em alcance próximo. Apenas criaturas à sua escolha podem entrar. Lá dentro, você pode tornar a entrada invisível. Você e quem estiver dentro sempre podem sair. Depois que sair, a porta precisa ser invocada novamente. Ao descansar dentro do seu Refúgio Seguro, você pode escolher um movimento de descanso adicional." },
  { id: "book-of-ronin", domain: "codice", level: 9, type: "grimorio", recall: 4, name: "Livro de Ronin", text: "Transformar: faça um teste de conjuração (15). Em um sucesso, transforme-se em um objeto inanimado de no máximo o dobro do seu tamanho normal. Você pode permanecer nessa forma até sofrer dano.\nEnfraquecimento Eterno: uma vez por descanso longo, faça um teste de conjuração contra um alvo em alcance próximo. Em um sucesso, ele fica permanentemente Vulnerável e não pode remover essa condição de nenhuma forma." },
  { id: "disintegration-wave", domain: "codice", level: 9, type: "feitico", recall: 4, name: "Onda Desintegradora", text: "Faça um teste de conjuração (18). Uma vez por descanso longo, em um sucesso, o mestre diz quais adversários em alcance distante têm Dificuldade 18 ou menor. Marque 1 Ponto de Fadiga para cada um que deseje atingir com este feitiço. Eles morrem e não podem voltar à vida por nenhum meio." },
  { id: "book-of-yarrow", domain: "codice", level: 10, type: "grimorio", recall: 2, name: "Livro de Yarrow", text: "Congelar o Tempo: faça um teste de conjuração (18). Em um sucesso, o tempo para temporariamente para todos em alcance distante, exceto você. Ele volta a correr na próxima vez que você fizer um teste que tenha outra criatura como alvo.\nImunidade Mágica: gaste 5 Pontos de Esperança para ficar imune a dano mágico até o próximo descanso." },
  { id: "transcendent-union", domain: "codice", level: 10, type: "feitico", recall: 1, name: "União Transcendental", text: "Uma vez por descanso longo, gaste 5 Pontos de Esperança para conjurar este feitiço em duas ou mais criaturas voluntárias. Até o próximo descanso, quando uma criatura ligada por esta união for marcar Fadiga ou Pontos de Vida, as criaturas ligadas podem escolher quem marca." },
  { id: "deft-deceiver", domain: "graca", level: 1, type: "talento", recall: 0, name: "Dissimulação", text: "Gaste 1 Ponto de Esperança para receber vantagem em um teste para enganar ou fazer alguém acreditar em uma mentira que você contar." },
  { id: "enrapture", domain: "graca", level: 1, type: "feitico", recall: 0, name: "Enfeitiçar", text: "Faça um teste de conjuração contra um alvo em alcance próximo. Em um sucesso, ele fica temporariamente Enfeitiçado. Enquanto estiver Enfeitiçado, a atenção do alvo fica fixa em você, estreitando seu campo de visão e abafando qualquer som que não seja a sua voz. Uma vez por descanso, em um sucesso, você pode marcar 1 Ponto de Fadiga para forçar o alvo Enfeitiçado a marcar 1 Ponto de Fadiga também." },
  { id: "inspirational-words", domain: "graca", level: 1, type: "talento", recall: 1, name: "Palavras Inspiradoras", text: "Seu discurso é imbuído de poder. Depois de um descanso longo, coloque nesta carta um número de marcadores igual à sua Presença. Ao falar com um aliado, você pode gastar um marcador desta carta para dar a ele um benefício, entre as opções:\n• Seu aliado recupera 1 Ponto de Fadiga;\n• Seu aliado recupera 1 Ponto de Vida;\n• Seu aliado recebe 1 Ponto de Esperança.\nAo fazer um descanso longo, perca os marcadores não utilizados." },
  { id: "tell-no-lies", domain: "graca", level: 2, type: "feitico", recall: 1, name: "Não Minta Para Mim", text: "Faça um teste de conjuração contra um alvo em alcance muito próximo. Em um sucesso, ele não consegue mentir para você enquanto estiver em alcance próximo, mas não é obrigado a falar. Se você fizer uma pergunta e ele se recusar a responder, ele deve marcar 1 Ponto de Fadiga e o efeito termina. O alvo normalmente não percebe que o feitiço foi lançado até ser forçado a dizer a verdade." },
  { id: "troublemaker", domain: "graca", level: 2, type: "talento", recall: 2, name: "Insolência", text: "Ao provocar ou ridicularizar um alvo em alcance distante, faça um teste de Presença contra ele. Uma vez por descanso, em um sucesso, role um número de d4 igual à sua Proficiência. O alvo deve marcar Fadiga igual ao maior resultado." },
  { id: "hypnotic-shimmer", domain: "graca", level: 3, type: "feitico", recall: 1, name: "Lampejo Hipnótico", text: "Faça um teste de conjuração contra todos os adversários à sua frente em alcance próximo. Uma vez por descanso, em um sucesso, crie uma ilusão de luzes e cores piscantes que deixa temporariamente Atordoados os alvos em que você tiver sucesso e os força a marcar 1 Ponto de Fadiga. Enquanto estiverem Atordoados, eles não podem usar reações nem realizar outras ações até removerem essa condição." },
  { id: "invisibility", domain: "graca", level: 3, type: "feitico", recall: 1, name: "Invisibilidade", text: "Faça um teste de conjuração (10). Em um sucesso, marque 1 Ponto de Fadiga e escolha você mesmo ou um aliado em alcance corpo a corpo para ficar Invisível. Uma criatura Invisível não pode ser vista, a não ser por meios mágicos, e testes de ataque contra ela são feitos com desvantagem. Coloque nesta carta um número de marcadores igual ao seu atributo de conjuração. Quando a criatura Invisível realizar uma ação, gaste um marcador. Depois que a ação que gasta o último marcador for resolvida, o efeito acaba. Você só pode manter Invisibilidade em uma criatura por vez." },
  { id: "soothing-speech", domain: "graca", level: 4, type: "talento", recall: 1, name: "Discurso Tranquilizante", text: "Durante um descanso curto, quando você dedicar tempo a confortar outro personagem enquanto usa nele o movimento Cuidar dos Ferimentos, ele recupera 1 Ponto de Vida adicional. Ao fazer isso, você também recupera 2 Pontos de Vida." },
  { id: "through-your-eyes", domain: "graca", level: 4, type: "feitico", recall: 1, name: "Espionar", text: "Escolha um alvo em alcance muito distante. Você pode ver pelos olhos e ouvir pelos ouvidos dele, alternando livremente entre seus próprios sentidos e os do alvo até conjurar outro feitiço ou até o próximo descanso." },
  { id: "thought-delver", domain: "graca", level: 5, type: "feitico", recall: 2, name: "Sondar Pensamentos", text: "Você pode espiar a mente dos outros. Gaste 1 Ponto de Esperança para ler os pensamentos vagos e superficiais de um alvo em alcance distante. Faça um teste de conjuração contra o alvo para mergulhar em pensamentos mais profundos e escondidos. Em um resultado com Medo, o alvo pode, a critério do mestre, perceber que você está lendo os pensamentos dele." },
  { id: "words-of-discord", domain: "graca", level: 5, type: "feitico", recall: 1, name: "Palavras de Discórdia", text: "Sussurre palavras de discórdia a um adversário em alcance corpo a corpo e faça um teste de conjuração (13). Em um sucesso, o alvo deve marcar 1 Ponto de Fadiga e atacar outro adversário em vez de atacar você ou seus aliados. Quando o ataque acabar, o alvo percebe o que aconteceu. Na próxima vez que você conjurar Palavras de Discórdia nele, receba −5 de penalidade no teste de conjuração." },
  { id: "never-upstaged", domain: "graca", level: 6, type: "talento", recall: 2, name: "Jamais Esquecido", text: "Ao marcar 1 ou mais Pontos de Vida por causa de um ataque, você pode marcar 1 Ponto de Fadiga para colocar nesta carta um número de marcadores igual ao de Pontos de Vida marcados. No próximo ataque bem-sucedido, receba +5 de bônus na rolagem de dano para cada marcador desta carta e depois remova todos os marcadores." },
  { id: "share-the-burden", domain: "graca", level: 6, type: "feitico", recall: 0, name: "Partilhar o Fardo", text: "Uma vez por descanso, assuma a Fadiga de uma criatura voluntária em alcance corpo a corpo. O alvo descreve que conhecimento íntimo ou emoções vazam telepaticamente da mente dele nesse momento entre vocês. Transfira para você qualquer número de Pontos de Fadiga marcados por ele e receba 1 Ponto de Esperança para cada Ponto de Fadiga transferido." },
  { id: "endless-charisma", domain: "graca", level: 7, type: "talento", recall: 1, name: "Carisma Infinito", text: "Depois de fazer um teste para persuadir, mentir ou conquistar favores, você pode gastar 1 Ponto de Esperança para rolar novamente o Dado de Esperança ou o Dado de Medo." },
  { id: "grace-touched", domain: "graca", level: 7, type: "talento", recall: 2, name: "Dom da Graça", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Graça, receba os benefícios a seguir:\n• Você pode marcar 1 Ponto de Armadura em vez de marcar 1 Ponto de Fadiga;\n• Ao forçar um alvo a marcar um número de Pontos de Vida, você pode escolher forçá-lo a marcar esse número de Pontos de Fadiga." },
  { id: "astral-projection", domain: "graca", level: 8, type: "feitico", recall: 0, name: "Projeção Astral", text: "Uma vez por descanso longo, marque 1 Ponto de Fadiga para criar uma cópia projetada de você que pode aparecer em qualquer lugar onde você já esteve. Você vê e ouve pela projeção como se fosse você e afeta o mundo como se estivesse lá. Uma criatura que investigue a projeção percebe que ela tem origem mágica. O efeito dura até o próximo descanso ou até a projeção sofrer qualquer dano." },
  { id: "mass-enrapture", domain: "graca", level: 8, type: "feitico", recall: 3, name: "Enfeitiçar em Massa", text: "Faça um teste de conjuração contra todos os alvos em alcance distante. Os alvos em que você tiver sucesso ficam temporariamente Enfeitiçados. Enquanto estiver Enfeitiçado, a atenção do alvo fica fixa em você, estreitando seu campo de visão e abafando qualquer som que não seja a sua voz. Marque 1 Ponto de Fadiga para forçar todos os alvos Enfeitiçados a marcar 1 Ponto de Fadiga, encerrando este feitiço." },
  { id: "copycat", domain: "graca", level: 9, type: "feitico", recall: 3, name: "Imitador", text: "Uma vez por descanso longo, esta carta pode imitar as habilidades de outra carta de domínio de nível 8 ou menor na mão de outro jogador. Gaste Pontos de Esperança iguais à metade do nível da carta para ter acesso à habilidade. Ela dura até o próximo descanso ou até o outro jogador colocar a carta na reserva." },
  { id: "master-of-the-craft", domain: "graca", level: 9, type: "talento", recall: 0, name: "Mestre do Ofício", text: "Receba permanentemente +2 de bônus em duas das suas Experiências ou +3 de bônus em uma delas. Depois, coloque esta carta permanentemente na sua reserva." },
  { id: "encore", domain: "graca", level: 10, type: "feitico", recall: 1, name: "Em Dobro", text: "Quando um aliado em alcance próximo causar dano a um adversário, você pode fazer um teste de conjuração contra esse mesmo alvo. Em um sucesso, você causa ao alvo o mesmo dano que seu aliado causou. Se o teste de conjuração for um sucesso com Medo, coloque esta carta na sua reserva." },
  { id: "notorious", domain: "graca", level: 10, type: "talento", recall: 0, name: "Notoriedade", text: "As pessoas sabem quem você é e o que fez, e o tratam de forma diferente por isso. Ao usar sua notoriedade para conseguir o que quer, você pode marcar 1 Ponto de Fadiga antes de rolar para receber +10 de bônus no resultado. Suas comidas e bebidas são sempre de graça onde quer que você vá, e tudo o mais que comprar custa um saco de ouro a menos (mínimo de um punhado). Esta carta não conta no limite de 5 cartas de domínio da sua mão e não pode ser colocada na reserva." },
  { id: "pick-and-pull", domain: "meia_noite", level: 1, type: "talento", recall: 0, name: "Delinquente", text: "Você tem vantagem em testes para arrombar fechaduras não mágicas, desarmar armadilhas não mágicas ou roubar itens de um alvo (furtivamente ou à força)." },
  { id: "rain-of-blades", domain: "meia_noite", level: 1, type: "feitico", recall: 1, name: "Chuva de Lâminas", text: "Gaste 1 Ponto de Esperança para fazer um teste de conjuração e invocar lâminas de arremesso que atingem todos os alvos em alcance muito próximo. Os alvos em que você tiver sucesso sofrem d8+2 de dano mágico, usando sua Proficiência. Se um alvo atingido estiver Vulnerável, ele sofre 1d8 de dano adicional." },
  { id: "uncanny-disguise", domain: "meia_noite", level: 1, type: "feitico", recall: 0, name: "Disfarce Inquietante", text: "Com alguns minutos para se preparar, você pode marcar 1 Ponto de Fadiga para assumir a aparência de qualquer humanoide que consiga imaginar com clareza. Disfarçado, você tem vantagem em testes de Presença para evitar ser examinado. Coloque nesta carta um número de marcadores igual ao seu atributo de conjuração. Ao realizar uma ação disfarçado, gaste um marcador. Depois que a ação que gasta o último marcador for resolvida, o disfarce cai." },
  { id: "midnight-spirit", domain: "meia_noite", level: 2, type: "feitico", recall: 1, name: "Espírito da Meia-noite", text: "Gaste 1 Ponto de Esperança para invocar um espírito do tamanho de um humanoide que pode mover ou carregar coisas para você até o próximo descanso. Você também pode enviá-lo para atacar um adversário. Para isso, faça um teste de conjuração contra um alvo em alcance muito distante. Em um sucesso, o espírito se move até alcance corpo a corpo do alvo. Role um número de d6 igual ao seu atributo de conjuração e cause esse total como dano mágico ao alvo. Depois o espírito se dissipa. Você só pode ter um espírito por vez." },
  { id: "shadowbind", domain: "meia_noite", level: 2, type: "feitico", recall: 0, name: "Sombra Traiçoeira", text: "Faça um teste de conjuração contra todos os adversários em alcance muito próximo. Os alvos em que você tiver sucesso ficam temporariamente Imobilizados, presos no lugar pela própria sombra." },
  { id: "chokehold", domain: "meia_noite", level: 3, type: "talento", recall: 1, name: "Estrangulamento", text: "Quando você se posicionar atrás de uma criatura de tamanho parecido com o seu, pode marcar 1 Ponto de Fadiga para aplicar uma gravata, deixando-a temporariamente Vulnerável. Quando uma criatura atacar um alvo Vulnerável dessa forma, ela causa 2d6 de dano adicional." },
  { id: "veil-of-night", domain: "meia_noite", level: 3, type: "feitico", recall: 1, name: "Véu da Noite", text: "Faça um teste de conjuração (13). Em um sucesso, você cria uma cortina temporária de escuridão entre dois pontos em alcance distante. Só você enxerga através dela. Você é considerado Escondido para adversários do outro lado do véu e tem vantagem nos ataques feitos através da escuridão. O véu permanece até você conjurar outro feitiço." },
  { id: "stealth-expertise", domain: "meia_noite", level: 4, type: "talento", recall: 0, name: "Mestre da Furtividade", text: "Ao rolar com Medo tentando se mover sem ser notado por uma área perigosa, você pode marcar 1 Ponto de Fadiga para rolar com Esperança em vez disso. Se um aliado em alcance próximo também estiver tentando passar despercebido e rolar com Medo, você pode marcar 1 Ponto de Fadiga para mudar o resultado dele para Esperança." },
  { id: "glyph-of-nightfall", domain: "meia_noite", level: 4, type: "feitico", recall: 1, name: "Glifo do Ocaso", text: "Faça um teste de conjuração contra um alvo em alcance muito próximo. Em um sucesso, gaste 1 Ponto de Esperança para conjurar um glifo escuro sobre o corpo dele que expõe seus pontos fracos, reduzindo temporariamente a Dificuldade do alvo em um valor igual ao seu Conhecimento (mínimo 1)." },
  { id: "hush", domain: "meia_noite", level: 5, type: "feitico", recall: 1, name: "Silêncio", text: "Faça um teste de conjuração contra um alvo em alcance próximo. Em um sucesso, gaste 1 Ponto de Esperança para conjurar magia supressora ao redor do alvo, abrangendo tudo em alcance muito próximo dele e acompanhando-o quando ele se mover. O alvo e tudo na área ficam Silenciados até o mestre gastar 1 Ponto de Medo no turno dele para remover a condição, você conjurar Silêncio de novo ou sofrer dano maior. Enquanto Silenciados, não podem fazer barulho nem conjurar feitiços." },
  { id: "phantom-retreat", domain: "meia_noite", level: 5, type: "feitico", recall: 2, name: "Recuo Espectral", text: "Gaste 1 Ponto de Esperança para ativar Recuo Espectral onde você está. Gaste outro Ponto de Esperança a qualquer momento antes do próximo descanso para desaparecer de onde está e reaparecer onde estava ao ativar o Recuo Espectral. O feitiço acaba depois que você reaparece." },
  { id: "dark-whispers", domain: "meia_noite", level: 6, type: "feitico", recall: 0, name: "Sussurros Sombrios", text: "Você pode falar na mente de qualquer pessoa com quem teve contato físico. Depois de abrir o canal, ela também pode falar na sua mente. Além disso, você pode marcar 1 Ponto de Fadiga para fazer um teste de conjuração contra ela. Em um sucesso, você pode fazer ao mestre uma das perguntas a seguir e receber a resposta:\n• Onde ela está?\n• O que ela está fazendo?\n• Do que ela tem medo?\n• O que ela mais valoriza no mundo?" },
  { id: "mass-disguise", domain: "meia_noite", level: 6, type: "feitico", recall: 0, name: "Disfarce em Massa", text: "Com alguns minutos de silêncio para se concentrar, você pode marcar 1 Ponto de Fadiga para mudar a aparência de todas as criaturas voluntárias em alcance próximo. As novas formas devem ter estrutura corporal e tamanho semelhantes e podem ser de alguém ou algo que você já viu, ou totalmente inventadas. Uma criatura disfarçada tem vantagem em testes de Presença para evitar ser examinada. Ative uma Contagem Regressiva (8), que diminui como consequência escolhida pelo mestre. Quando ela terminar, o disfarce cai." },
  { id: "midnight-touched", domain: "meia_noite", level: 7, type: "talento", recall: 2, name: "Dom da Meia-noite", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Meia-noite, receba os benefícios a seguir:\n• Uma vez por descanso, quando você tiver 0 Pontos de Esperança e o mestre for receber 1 Ponto de Medo, você pode receber 1 Ponto de Esperança em vez disso;\n• Ao acertar um ataque, você pode marcar 1 Ponto de Fadiga para somar o resultado do seu Dado de Medo à rolagem de dano." },
  { id: "vanishing-dodge", domain: "meia_noite", level: 7, type: "feitico", recall: 1, name: "Esvanecer", text: "Quando um ataque feito contra você que causaria dano físico falhar, você pode gastar 1 Ponto de Esperança para se envolver em sombras, ficando Escondido e se teletransportando para um ponto em alcance próximo do atacante. Você permanece Escondido até a próxima vez que fizer um teste." },
  { id: "shadowhunter", domain: "meia_noite", level: 8, type: "talento", recall: 2, name: "Caçador Sombrio", text: "Sua habilidade aumenta sob o abrigo das sombras. Enquanto estiver em penumbra ou escuridão, você recebe +1 de bônus na Evasão e faz testes de ataque com vantagem." },
  { id: "spellcharge", domain: "meia_noite", level: 8, type: "feitico", recall: 1, name: "Carga Mágica", text: "Ao sofrer dano mágico, coloque nesta carta marcadores iguais ao número de Pontos de Vida que marcou. Você pode guardar um número de marcadores igual ao seu atributo de conjuração. Ao acertar um ataque contra um alvo, você pode gastar qualquer número de marcadores para somar 1d6 por marcador gasto à rolagem de dano." },
  { id: "night-terror", domain: "meia_noite", level: 9, type: "feitico", recall: 2, name: "Terror Noturno", text: "Uma vez por descanso longo, escolha quaisquer alvos em alcance muito próximo para que o percebam como um horror de pesadelo. Os alvos devem passar em um teste de reação (16) ou ficar temporariamente Aterrorizados. Enquanto estiverem Aterrorizados, ficam Vulneráveis. Roube do mestre um número de Pontos de Medo igual ao de alvos Aterrorizados (até o número de Pontos de Medo na reserva dele). Role um número de d6 igual ao de Pontos de Medo roubados e cause o total como dano a cada alvo Aterrorizado. Descarte os Pontos de Medo roubados." },
  { id: "twilight-toll", domain: "meia_noite", level: 9, type: "talento", recall: 1, name: "Tributo do Anoitecer", text: "Escolha um alvo em alcance distante. Quando você tiver sucesso em um teste contra ele que não resulte em rolagem de dano, coloque um marcador nesta carta. Ao causar dano a esse alvo, gaste qualquer número de marcadores para somar 1d12 por marcador gasto à rolagem de dano. Você só pode manter Tributo do Anoitecer em uma criatura por vez. Ao escolher um novo alvo ou fazer um descanso, remova os marcadores não utilizados." },
  { id: "eclipse", domain: "meia_noite", level: 10, type: "feitico", recall: 2, name: "Eclipse", text: "Faça um teste de conjuração (16). Uma vez por descanso longo, em um sucesso, mergulhe toda a área em alcance distante em escuridão completa que só você e seus aliados enxergam. Testes de ataque têm desvantagem contra você ou um aliado dentro dessa sombra. Além disso, quando você ou um aliado tiver sucesso com Esperança contra um adversário dentro da sombra, o alvo deve marcar 1 Ponto de Fadiga. O feitiço dura até o mestre gastar 1 Ponto de Medo no turno dele para encerrá-lo ou você sofrer dano grave." },
  { id: "specter-of-the-dark", domain: "meia_noite", level: 10, type: "feitico", recall: 1, name: "Espectro das Trevas", text: "Marque 1 Ponto de Fadiga para ficar Espectral até fazer um teste que tenha outra criatura como alvo. Enquanto estiver Espectral, você é imune a dano físico e pode flutuar e atravessar objetos sólidos. Outras criaturas ainda podem vê-lo nessa forma." },
  { id: "gifted-tracker", domain: "sabedoria", level: 1, type: "talento", recall: 0, name: "Rastreador Talentoso", text: "Ao rastrear uma criatura ou grupo de criaturas específico pelos sinais de sua passagem, você pode gastar qualquer número de Pontos de Esperança e fazer ao mestre essa quantidade de perguntas da lista a seguir:\n• Para que direção eles foram?\n• Há quanto tempo passaram por aqui?\n• O que estavam fazendo neste lugar?\n• Quantos deles estiveram aqui?\nAo encontrar criaturas rastreadas dessa forma, receba +1 de bônus na Evasão contra elas." },
  { id: "natures-tongue", domain: "sabedoria", level: 1, type: "talento", recall: 0, name: "Voz da Natureza", text: "Você fala a língua do mundo natural. Para conversar com as plantas e os animais ao redor, faça um teste de Instinto (12). Em um sucesso, eles lhe dão as informações que têm. Em um resultado com Medo, o conhecimento deles pode ser limitado ou ter um custo. Além disso, antes de fazer um teste de conjuração em um ambiente natural, você pode gastar 1 Ponto de Esperança para receber +2 de bônus no teste." },
  { id: "vicious-entangle", domain: "sabedoria", level: 1, type: "feitico", recall: 1, name: "Vinha Voraz", text: "Faça um teste de conjuração contra um alvo em alcance distante. Em um sucesso, raízes e vinhas brotam do chão, causando 1d8+1 de dano físico e Imobilizando temporariamente o alvo. Além disso, em um sucesso, você pode gastar 1 Ponto de Esperança para Imobilizar temporariamente outro adversário em alcance muito próximo do seu alvo." },
  { id: "conjure-swarm", domain: "sabedoria", level: 2, type: "feitico", recall: 1, name: "Conjurar Enxame", text: "Besouros Blindados Tekaira: marque 1 Ponto de Fadiga para conjurar besouros blindados que cercam você. Na próxima vez que sofrer dano, reduza a gravidade em uma categoria. Você pode gastar 1 Ponto de Esperança para manter os besouros depois de sofrer dano.\nVaga-lumes: faça um teste de conjuração contra todos os adversários em alcance próximo. Gaste 1 Ponto de Esperança para causar 2d8+3 de dano mágico aos alvos em que teve sucesso." },
  { id: "natural-familiar", domain: "sabedoria", level: 2, type: "feitico", recall: 1, name: "Familiar da Natureza", text: "Gaste 1 Ponto de Esperança para invocar um pequeno espírito da natureza ou um bichinho da floresta ao seu lado até o próximo descanso, até você conjurar Familiar da Natureza de novo ou até o familiar ser alvo de um ataque. Se gastar 1 Ponto de Esperança adicional, você pode invocar um familiar que voa. Você pode se comunicar com ele, fazer um teste de conjuração para ordenar tarefas simples e marcar 1 Ponto de Fadiga para ver pelos olhos dele. Ao causar dano a um adversário em alcance corpo a corpo do seu familiar, some 1d6 à rolagem de dano." },
  { id: "corrosive-projectile", domain: "sabedoria", level: 3, type: "feitico", recall: 1, name: "Projétil Corrosivo", text: "Faça um teste de conjuração contra um alvo em alcance distante. Em um sucesso, cause d6+4 de dano mágico, usando sua Proficiência. Além disso, marque 2 ou mais Pontos de Fadiga para deixá-lo permanentemente Corroído. Enquanto um alvo estiver Corroído, ele recebe −1 de penalidade na Dificuldade para cada 2 Pontos de Fadiga gastos. Essa condição se acumula." },
  { id: "towering-stalk", domain: "sabedoria", level: 3, type: "feitico", recall: 1, name: "Tronco Descomunal", text: "Uma vez por descanso, você pode conjurar um tronco grosso e retorcido, fácil de escalar, em alcance próximo. Ele pode crescer até alcance distante. Marque 1 Ponto de Fadiga para usar este feitiço como ataque. Faça um teste de conjuração contra um adversário ou grupo de adversários em alcance próximo. O tronco irrompe, levanta os alvos em que você teve sucesso e os derruba, causando d8 de dano físico, usando sua Proficiência." },
  { id: "death-grip", domain: "sabedoria", level: 4, type: "feitico", recall: 1, name: "Constrição Mortal", text: "Faça um teste de conjuração contra um alvo em alcance próximo e escolha uma das opções:\n• Você puxa o alvo para alcance corpo a corpo ou se puxa até ele;\n• Você aperta o alvo e o força a marcar 2 Pontos de Fadiga;\n• Todos os adversários entre você e o alvo devem passar em um teste de reação (13) ou serem atingidos pelas vinhas, sofrendo 3d6+2 de dano físico.\nEm um sucesso, vinhas saem das suas mãos, causando o efeito escolhido e Imobilizando temporariamente o alvo." },
  { id: "healing-field", domain: "sabedoria", level: 4, type: "feitico", recall: 2, name: "Campo Curativo", text: "Uma vez por descanso longo, você pode conjurar um campo de plantas curativas ao seu redor. Todo o alcance próximo ganha vida com natureza vibrante, permitindo que você e todos os aliados na área recuperem 1 Ponto de Vida. Gaste 2 Pontos de Esperança para que você e todos os aliados recuperem 2 Pontos de Vida." },
  { id: "thorn-skin", domain: "sabedoria", level: 5, type: "feitico", recall: 1, name: "Pele de Espinhos", text: "Uma vez por descanso, gaste 1 Ponto de Esperança para fazer espinhos brotarem por todo o corpo. Ao fazer isso, coloque nesta carta um número de marcadores igual ao seu atributo de conjuração. Ao sofrer dano, você pode gastar qualquer número de marcadores para rolar essa quantidade de d6. Some os resultados e reduza o dano sofrido nesse valor. Se estiver em alcance corpo a corpo do atacante, cause esse mesmo dano a ele. Ao fazer um descanso, remova os marcadores não utilizados." },
  { id: "wild-fortress", domain: "sabedoria", level: 5, type: "feitico", recall: 1, name: "Fortaleza Selvagem", text: "Faça um teste de conjuração (13). Em um sucesso, gaste 2 Pontos de Esperança para fazer crescer uma barricada natural em forma de domo, onde você e um aliado podem se abrigar. Dentro do domo, uma criatura não pode ser alvo de ataques nem fazer ataques. Ataques contra o domo sempre têm sucesso. O domo tem limiares de dano 15/30 e dura até marcar 3 Pontos de Vida. Coloque marcadores nesta carta para representar os Pontos de Vida marcados." },
  { id: "conjured-steeds", domain: "sabedoria", level: 6, type: "feitico", recall: 0, name: "Conjurar Montarias", text: "Gaste qualquer número de Pontos de Esperança para conjurar essa quantidade de montarias mágicas (como cavalos, camelos ou elefantes) que você e seus aliados podem montar até o próximo descanso longo ou até as montarias sofrerem qualquer dano. As montarias dobram sua velocidade em terra durante viagens e, em perigo, permitem que você se mova até alcance distante sem precisar rolar. Criaturas montadas recebem −2 de penalidade em testes de ataque e +2 de bônus em rolagens de dano." },
  { id: "forager", domain: "sabedoria", level: 6, type: "talento", recall: 1, name: "Coletor", text: "Como movimento de descanso adicional, você pode rolar 1d6 para ver o que coleta. Descreva o item com o mestre e adicione-o ao inventário como consumível. Seu grupo pode carregar até cinco consumíveis coletados por vez.\n1. Uma comida peculiar (recupere 2 Pontos de Fadiga);\n2. Uma bela relíquia (receba 2 Pontos de Esperança);\n3. Uma runa arcana (+2 em um teste de conjuração);\n4. Um frasco curativo (recupere 2 Pontos de Vida);\n5. Um amuleto da sorte (role novamente qualquer dado);\n6. Escolha uma das opções acima." },
  { id: "sage-touched", domain: "sabedoria", level: 7, type: "talento", recall: 2, name: "Dom da Sabedoria", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Sabedoria, receba os benefícios a seguir:\n• Em um ambiente natural, você recebe +2 de bônus em testes de conjuração;\n• Uma vez por descanso, você pode dobrar sua Agilidade ou seu Instinto ao fazer um teste que use esse atributo. Você deve escolher isso antes de rolar." },
  { id: "wild-surge", domain: "sabedoria", level: 7, type: "feitico", recall: 2, name: "Aspecto Selvagem", text: "Uma vez por descanso longo, marque 1 Ponto de Fadiga para canalizar o mundo natural ao redor e se fortalecer. Descreva como sua aparência muda e coloque 1d6 nesta carta com o valor 1 voltado para cima. Enquanto o Dado do Aspecto Selvagem estiver ativo, some o valor dele a todo teste que fizer. Depois de somar o valor a um teste, aumente o valor do dado em 1. Quando o valor for ultrapassar 6 ou você fizer um descanso, a forma se desfaz e você deve marcar 1 Ponto de Fadiga adicional." },
  { id: "forest-sprites", domain: "sabedoria", level: 8, type: "feitico", recall: 2, name: "Espíritos da Floresta", text: "Faça um teste de conjuração (13). Em um sucesso, gaste qualquer número de Pontos de Esperança para criar essa quantidade de pequenos espíritos da floresta em pontos à sua escolha em alcance distante, que concedem os benefícios a seguir:\n• Seus aliados recebem +3 de bônus em testes de ataque contra adversários em alcance corpo a corpo de um espírito;\n• Um aliado que marque 1 Ponto de Armadura em alcance corpo a corpo de um espírito pode marcar 1 Ponto de Armadura adicional.\nUm espírito desaparece depois de conceder um benefício ou sofrer qualquer dano." },
  { id: "rejuvenation-barrier", domain: "sabedoria", level: 8, type: "feitico", recall: 1, name: "Barreira Revigorante", text: "Faça um teste de conjuração (15). Uma vez por descanso, em um sucesso, crie uma barreira temporária de energia protetora ao seu redor, em alcance muito próximo. Você e todos os aliados dentro da barreira quando o feitiço for conjurado recuperam 1d4 Pontos de Vida. Enquanto a barreira estiver ativa, você e os aliados dentro dela têm resistência a dano físico vindo de fora. Quando você se mover, a barreira o acompanha." },
  { id: "fane-of-the-wilds", domain: "sabedoria", level: 9, type: "talento", recall: 2, name: "Santuário Selvagem", text: "Depois de um descanso longo, coloque nesta carta um número de marcadores igual ao número de cartas do domínio Sabedoria na sua mão e na sua reserva. Ao fazer um teste de conjuração, você pode gastar qualquer número de marcadores depois da rolagem para receber +1 de bônus por marcador gasto. Ao ter sucesso crítico em um teste de conjuração de um feitiço do domínio Sabedoria, receba 1 marcador. Ao fazer um descanso longo, remova os marcadores não utilizados." },
  { id: "plant-dominion", domain: "sabedoria", level: 9, type: "feitico", recall: 1, name: "Soberania Vegetal", text: "Faça um teste de conjuração (18). Uma vez por descanso longo, em um sucesso, você remodela o mundo natural, mudando a vegetação ao redor em qualquer ponto em alcance distante. Por exemplo, você pode fazer árvores crescerem instantaneamente, abrir um caminho em vinhas densas ou criar uma muralha de raízes." },
  { id: "force-of-nature", domain: "sabedoria", level: 10, type: "feitico", recall: 2, name: "Força da Natureza", text: "Marque 1 Ponto de Fadiga para se transformar em um enorme espírito da natureza, recebendo os benefícios a seguir:\n• Ao ter sucesso em um ataque ou teste de conjuração, receba +10 de bônus na rolagem de dano;\n• Ao causar dano suficiente para derrotar uma criatura em alcance próximo, você a absorve e recupera 1 Ponto de Armadura;\n• Você não pode ser Imobilizado.\nAntes de fazer um teste, você deve gastar 1 Ponto de Esperança. Se não puder, você volta à forma normal." },
  { id: "tempest", domain: "sabedoria", level: 10, type: "feitico", recall: 2, name: "Tempestade", text: "Escolha uma das tempestades a seguir e faça um teste de conjuração contra todos os alvos em alcance distante. Os alvos em que você tiver sucesso sofrem os efeitos até o mestre gastar 1 Ponto de Medo no turno dele para encerrar o feitiço.\n• Nevasca: cause 2d20+8 de dano mágico, e os alvos ficam temporariamente Vulneráveis;\n• Furacão: cause 3d10+10 de dano mágico e escolha a direção do vento. Os alvos não podem se mover contra o vento;\n• Tempestade de Areia: cause 5d6+9 de dano mágico. Ataques feitos de fora do alcance corpo a corpo têm desvantagem." },
  { id: "bolt-beacon", domain: "esplendor", level: 1, type: "feitico", recall: 1, name: "Raio Luminoso", text: "Faça um teste de conjuração contra um alvo em alcance distante. Em um sucesso, gaste 1 Ponto de Esperança para lançar um raio de luz cintilante contra ele, causando d8+2 de dano mágico, usando sua Proficiência. O alvo fica temporariamente Vulnerável e brilha intensamente até essa condição ser removida." },
  { id: "mending-touch", domain: "esplendor", level: 1, type: "feitico", recall: 1, name: "Toque Reparador", text: "Você impõe as mãos sobre uma criatura e canaliza magia de cura para fechar os ferimentos dela. Quando puder dedicar alguns minutos ao alvo, você pode gastar 2 Pontos de Esperança para que ele recupere 1 Ponto de Vida ou 1 Ponto de Fadiga. Uma vez por descanso longo, se usar esse tempo para aprender algo novo sobre o alvo ou revelar algo sobre você, ele recupera 2 Pontos de Vida ou 2 Pontos de Fadiga." },
  { id: "reassurance", domain: "esplendor", level: 1, type: "talento", recall: 0, name: "Validação", text: "Uma vez por descanso, depois que um aliado tentar um teste, mas antes de as consequências acontecerem, você pode oferecer ajuda ou palavras de apoio. Se fizer isso, seu aliado pode rolar os dados novamente." },
  { id: "final-words", domain: "esplendor", level: 2, type: "feitico", recall: 1, name: "Últimas Palavras", text: "Você pode infundir um cadáver com um instante de vida para conversar com ele. Faça um teste de conjuração (13). Em um sucesso com Esperança, o cadáver responde a até três perguntas. Em um sucesso com Medo, responde a uma pergunta. O cadáver responde com sinceridade, mas não pode revelar o que não sabia em vida. Em uma falha, ou quando terminar de responder, o corpo vira pó." },
  { id: "healing-hands", domain: "esplendor", level: 2, type: "feitico", recall: 1, name: "Mãos Curativas", text: "Faça um teste de conjuração (13) e escolha uma criatura que não seja você em alcance corpo a corpo. Em um sucesso, marque 1 Ponto de Fadiga para que o alvo recupere 2 Pontos de Vida ou 2 Pontos de Fadiga. Em uma falha, marque 1 Ponto de Fadiga para que o alvo recupere 1 Ponto de Vida ou 1 Ponto de Fadiga. Você não pode curar o mesmo alvo de novo até o próximo descanso longo." },
  { id: "second-wind", domain: "esplendor", level: 3, type: "talento", recall: 2, name: "Novo Fôlego", text: "Uma vez por descanso, ao acertar um ataque contra um adversário, você pode recuperar 3 Pontos de Fadiga ou 1 Ponto de Vida. Em um sucesso com Esperança, você também recupera 3 Pontos de Fadiga ou 1 Ponto de Vida de um aliado em alcance próximo." },
  { id: "voice-of-reason", domain: "esplendor", level: 3, type: "talento", recall: 1, name: "Voz da Razão", text: "Você fala com um poder e uma autoridade incomparáveis. Você tem vantagem em testes para apaziguar situações violentas ou convencer alguém a seguir sua liderança. Além disso, você se fortalece em momentos de aperto: quando todos os seus espaços de Fadiga estiverem marcados, receba +1 de bônus na Proficiência nas rolagens de dano." },
  { id: "divination", domain: "esplendor", level: 4, type: "feitico", recall: 1, name: "Adivinhação", text: "Uma vez por descanso longo, gaste 3 Pontos de Esperança para alcançar as forças do além e fazer uma pergunta de “sim ou não” sobre um evento, pessoa, lugar ou situação do futuro próximo. Por um instante, o presente se dissolve e você vê a resposta diante de si." },
  { id: "life-ward", domain: "esplendor", level: 4, type: "feitico", recall: 1, name: "Sigilo da Vida", text: "Gaste 3 Pontos de Esperança e escolha um aliado em alcance próximo. Ele é marcado com um sigilo luminoso de proteção. Quando esse aliado for fazer um movimento de morte, ele recupera 1 Ponto de Vida em vez disso. O efeito acaba quando salvar o alvo de um movimento de morte, você conjurar Sigilo da Vida em outro alvo ou fizer um descanso longo." },
  { id: "shape-material", domain: "esplendor", level: 5, type: "feitico", recall: 1, name: "Moldar Material", text: "Gaste 1 Ponto de Esperança para moldar uma porção de material natural que você esteja tocando (como pedra, gelo ou madeira) conforme sua necessidade. A área do material não pode ser maior que você. Por exemplo, você pode formar uma ferramenta rudimentar ou criar uma porta. Você só afeta o material em alcance próximo de onde está tocando." },
  { id: "smite", domain: "esplendor", level: 5, type: "feitico", recall: 2, name: "Punição", text: "Uma vez por descanso, gaste 3 Pontos de Esperança para carregar sua poderosa punição. No próximo ataque com arma que acertar, dobre o resultado da rolagem de dano. Esse ataque causa dano mágico, independentemente do tipo de dano da arma." },
  { id: "restoration", domain: "esplendor", level: 6, type: "feitico", recall: 2, name: "Restauração", text: "Depois de um descanso longo, coloque nesta carta um número de marcadores igual ao seu atributo de conjuração. Toque uma criatura e gaste qualquer número de marcadores para que ela recupere 2 Pontos de Vida ou 2 Pontos de Fadiga por marcador gasto. Você também pode gastar um marcador ao tocar uma criatura para remover a condição Vulnerável ou curar uma enfermidade física ou mágica (o mestre pode exigir marcadores adicionais conforme a gravidade). Ao fazer um descanso longo, remova os marcadores não utilizados." },
  { id: "zone-of-protection", domain: "esplendor", level: 6, type: "feitico", recall: 2, name: "Zona de Proteção", text: "Faça um teste de conjuração (16). Uma vez por descanso longo, em um sucesso, escolha um ponto em alcance distante e crie ali uma zona de proteção visível para todos os aliados em alcance muito próximo desse ponto. Ao fazer isso, coloque 1d6 nesta carta com o valor 1 voltado para cima. Quando um aliado na zona sofrer dano, ele o reduz pelo valor do dado. Depois, aumente o valor do dado em 1. Quando o valor for ultrapassar 6, o efeito acaba." },
  { id: "healing-strike", domain: "esplendor", level: 7, type: "feitico", recall: 1, name: "Golpe Curativo", text: "Ao causar dano a um adversário, você pode gastar 2 Pontos de Esperança para que um aliado em alcance próximo recupere 1 Ponto de Vida." },
  { id: "splendor-touched", domain: "esplendor", level: 7, type: "talento", recall: 2, name: "Dom do Esplendor", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Esplendor, receba os benefícios a seguir:\n• +3 de bônus no limiar de dano grave;\n• Uma vez por descanso longo, quando o dano sofrido exigir marcar um número de Pontos de Vida, você pode escolher marcar essa quantidade de Pontos de Fadiga ou gastar essa quantidade de Pontos de Esperança." },
  { id: "shield-aura", domain: "esplendor", level: 8, type: "feitico", recall: 2, name: "Aura Defensora", text: "Marque 1 Ponto de Fadiga para lançar uma aura protetora sobre um alvo em alcance muito próximo. Quando o alvo marcar 1 Ponto de Armadura, ele reduz a gravidade do ataque em mais uma categoria. Se este feitiço fizer uma criatura que sofreria dano não marcar nenhum Ponto de Vida, o efeito acaba. Você só pode manter Aura Defensora em uma criatura por vez." },
  { id: "stunning-sunlight", domain: "esplendor", level: 8, type: "feitico", recall: 2, name: "Fulgor Atordoante", text: "Faça um teste de conjuração para liberar poderosos raios de sol abrasador contra todos os adversários à sua frente em alcance distante. Em um sucesso, gaste qualquer número de Pontos de Esperança e force essa quantidade de alvos em que teve sucesso a fazer um teste de reação (14). Os alvos que passarem sofrem 3d20+3 de dano mágico. Os que falharem sofrem 4d20+5 de dano mágico e ficam temporariamente Atordoados. Enquanto Atordoados, não podem usar reações nem realizar outras ações até removerem essa condição." },
  { id: "overwhelming-aura", domain: "esplendor", level: 9, type: "feitico", recall: 2, name: "Aura Esmagadora", text: "Faça um teste de conjuração (15) para fortalecer magicamente sua aura. Em um sucesso, gaste 2 Pontos de Esperança para tornar sua Presença igual ao seu atributo de conjuração até o próximo descanso longo. Enquanto o feitiço estiver ativo, um adversário deve marcar 1 Ponto de Fadiga ao atacar você." },
  { id: "salvation-beam", domain: "esplendor", level: 9, type: "feitico", recall: 2, name: "Feixe de Remissão", text: "Faça um teste de conjuração (16). Em um sucesso, marque qualquer número de Pontos de Fadiga para escolher uma linha de aliados em alcance distante. Você pode curar Pontos de Vida dos alvos em um total igual ao número de Pontos de Fadiga marcados, dividido entre eles como preferir." },
  { id: "invigoration", domain: "esplendor", level: 10, type: "feitico", recall: 3, name: "Revigorar", text: "Quando você ou um aliado em alcance próximo tiver usado uma habilidade com limite de uso (como uma vez por descanso ou por sessão), você pode gastar qualquer número de Pontos de Esperança e rolar essa quantidade de d6. Se algum resultado for 6, a habilidade pode ser usada novamente." },
  { id: "resurrection", domain: "esplendor", level: 10, type: "feitico", recall: 2, name: "Ressurreição", text: "Faça um teste de conjuração (20). Em um sucesso, restaure à plena força uma criatura que esteja morta há no máximo 100 anos. Depois, role 1d6. Com resultado 5 ou menos, coloque esta carta permanentemente na sua reserva. Em uma falha, você não pode conjurar Ressurreição novamente por uma semana." },
  { id: "bare-bones", domain: "valor", level: 1, type: "talento", recall: 0, name: "Armadura Corporal", text: "Quando você escolhe não equipar armadura, sua Armadura base é 3 + sua Força, e você usa os seguintes limiares de dano base:\n• Patamar 1: 9/19;\n• Patamar 2: 11/24;\n• Patamar 3: 13/31;\n• Patamar 4: 15/38." },
  { id: "forceful-push", domain: "valor", level: 1, type: "talento", recall: 0, name: "Imposição", text: "Faça um ataque com sua arma principal contra um alvo em alcance corpo a corpo. Em um sucesso, você causa dano e o empurra para alcance próximo. Em um sucesso com Esperança, some 1d6 à rolagem de dano. Além disso, você pode gastar 1 Ponto de Esperança para deixá-lo temporariamente Vulnerável." },
  { id: "i-am-your-shield", domain: "valor", level: 1, type: "talento", recall: 1, name: "Sou Seu Escudo", text: "Quando um aliado em alcance muito próximo for sofrer dano, você pode marcar 1 Ponto de Fadiga para se colocar no caminho e se tornar o alvo do ataque. Ao sofrer dano desse ataque, você pode marcar qualquer número de Pontos de Armadura." },
  { id: "body-basher", domain: "valor", level: 2, type: "talento", recall: 1, name: "Força Esmagadora", text: "Você usa toda a força do corpo na luta. Ao acertar um ataque com uma arma de alcance corpo a corpo, receba um bônus na rolagem de dano igual à sua Força." },
  { id: "bold-presence", domain: "valor", level: 2, type: "talento", recall: 0, name: "Presença Corajosa", text: "Ao fazer um teste de Presença, você pode gastar 1 Ponto de Esperança para somar sua Força ao teste. Além disso, uma vez por descanso, quando for receber uma condição, você pode descrever como sua presença corajosa ajuda na situação e evitar receber a condição." },
  { id: "critical-inspiration", domain: "valor", level: 3, type: "talento", recall: 1, name: "Inspiração Crítica", text: "Uma vez por descanso, ao ter sucesso crítico em um ataque, todos os aliados em alcance muito próximo podem recuperar 1 Ponto de Fadiga ou receber 1 Ponto de Esperança." },
  { id: "lean-on-me", domain: "valor", level: 3, type: "talento", recall: 1, name: "Palavras de Conforto", text: "Uma vez por descanso longo, ao consolar ou inspirar um aliado que falhou em um teste, vocês dois recuperam 2 Pontos de Fadiga." },
  { id: "goad-them-on", domain: "valor", level: 4, type: "talento", recall: 1, name: "Incitar", text: "Descreva como você provoca um alvo em alcance próximo e faça um teste de Presença contra ele. Em um sucesso, o alvo deve marcar 1 Ponto de Fadiga e, na próxima vez que o mestre der o foco a ele, deve atacar você, com desvantagem." },
  { id: "support-tank", domain: "valor", level: 4, type: "talento", recall: 2, name: "Bastião", text: "Quando um aliado em alcance próximo falhar em um teste, você pode gastar 2 Pontos de Esperança para permitir que ele role novamente o Dado de Esperança ou o Dado de Medo." },
  { id: "armorer", domain: "valor", level: 5, type: "talento", recall: 1, name: "Armeiro", text: "Enquanto estiver usando armadura, receba +1 de bônus na Armadura. Durante um descanso, quando escolher consertar sua armadura como movimento de descanso, seus aliados também recuperam 1 Ponto de Armadura." },
  { id: "rousing-strike", domain: "valor", level: 5, type: "talento", recall: 1, name: "Golpe Inspirador", text: "Uma vez por descanso, ao ter sucesso crítico em um ataque, você e todos os aliados que puderem ver ou ouvir você recuperam 1 Ponto de Vida ou 1d4 Pontos de Fadiga." },
  { id: "inevitable", domain: "valor", level: 6, type: "talento", recall: 1, name: "Inevitável", text: "Quando falhar em um teste, o seu próximo teste tem vantagem." },
  { id: "rise-up", domain: "valor", level: 6, type: "talento", recall: 2, name: "Altivez", text: "Receba um bônus no limiar de dano grave igual à sua Proficiência. Ao marcar 1 ou mais Pontos de Vida por causa de um ataque, recupere 1 Ponto de Fadiga." },
  { id: "shrug-it-off", domain: "valor", level: 7, type: "talento", recall: 1, name: "Desprezar Fraqueza", text: "Ao sofrer dano, você pode marcar 1 Ponto de Fadiga para reduzir a gravidade do dano em uma categoria. Ao fazer isso, role 1d6. Com resultado 3 ou menos, coloque esta carta na sua reserva." },
  { id: "valor-touched", domain: "valor", level: 7, type: "talento", recall: 1, name: "Dom do Valor", text: "Se 4 ou mais das cartas de domínio na sua mão forem do domínio Valor, receba os benefícios a seguir:\n• +1 de bônus na Armadura;\n• Ao marcar 1 ou mais Pontos de Vida sem marcar um Ponto de Armadura, recupere 1 Ponto de Armadura." },
  { id: "full-surge", domain: "valor", level: 8, type: "talento", recall: 1, name: "Testar os Limites", text: "Uma vez por descanso longo, marque 3 Pontos de Fadiga para levar o corpo ao limite. Receba +2 de bônus em todos os seus atributos até o próximo descanso." },
  { id: "ground-pound", domain: "valor", level: 8, type: "talento", recall: 2, name: "Abalo Sísmico", text: "Gaste 2 Pontos de Esperança para golpear o chão onde está e fazer um teste de Força contra todos os alvos em alcance muito próximo. Os alvos em que você tiver sucesso são arremessados para alcance distante e devem fazer um teste de reação (17). Os que falharem sofrem 4d10+8 de dano. Os que passarem sofrem metade do dano." },
  { id: "hold-the-line", domain: "valor", level: 9, type: "talento", recall: 1, name: "Manter Posição", text: "Descreva a postura defensiva que você assume e gaste 1 Ponto de Esperança. Se um adversário se mover para alcance muito próximo, ele é puxado para alcance corpo a corpo e fica Imobilizado. A condição dura até você se mover ou falhar com Medo, ou até o mestre gastar 2 Pontos de Medo no turno dele para removê-la." },
  { id: "lead-by-example", domain: "valor", level: 9, type: "talento", recall: 3, name: "Líder Exemplar", text: "Ao causar dano a um adversário, você pode marcar 1 Ponto de Fadiga e descrever como incentiva seus aliados. O próximo personagem a atacar esse adversário pode recuperar 1 Ponto de Fadiga ou receber 1 Ponto de Esperança." },
  { id: "unbreakable", domain: "valor", level: 10, type: "talento", recall: 4, name: "Invencível", text: "Ao marcar seu último Ponto de Vida, em vez de fazer um movimento de morte, você pode rolar 1d6 e recuperar Pontos de Vida igual ao resultado. Depois, coloque esta carta na sua reserva." },
  { id: "unyielding-armor", domain: "valor", level: 10, type: "talento", recall: 1, name: "Defesa Irredutível", text: "Ao marcar 1 Ponto de Armadura, role um número de d6 igual à sua Proficiência. Se algum resultado for 6, reduza a gravidade em uma categoria sem marcar o Ponto de Armadura." },
]

const BY_ID = new Map(DOMAIN_CARDS.map((c) => [c.id, c]))

export function domainCard(id: string): DhDomainCard | undefined {
  return BY_ID.get(id)
}
